insert into public.grow_items (id, kind, title, body, reference, source_name, source_url, sort_order) values
  ('scripture-matthew-6-9-13', 'scripture', 'The Lord’s Prayer', 'Pray like this: ‘Our Father in heaven, may your name be kept holy. Let your Kingdom come. Let your will be done on earth as it is in heaven. Give us today our daily bread. Forgive us our debts, as we also forgive our debtors. Bring us not into temptation, but deliver us from the evil one. For yours is the Kingdom, the power, and the glory forever. Amen.’', 'Matthew 6:9–13 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 10),
  ('scripture-matthew-6-6', 'scripture', 'Pray in secret', 'But you, when you pray, enter into your inner room, and having shut your door, pray to your Father who is in secret, and your Father who sees in secret will reward you openly.', 'Matthew 6:6 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 11),
  ('scripture-matthew-7-7-8', 'scripture', 'Ask, seek, knock', '“Ask, and it will be given you. Seek, and you will find. Knock, and it will be opened for you. For everyone who asks receives. He who seeks finds. To him who knocks it will be opened.', 'Matthew 7:7–8 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 12),
  ('scripture-luke-18-1', 'scripture', 'Always pray, and don’t give up', 'He also spoke a parable to them that they must always pray, and not give up', 'Luke 18:1 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 13),
  ('scripture-philippians-4-6-7', 'scripture', 'Peace instead of anxiety', 'In nothing be anxious, but in everything, by prayer and petition with thanksgiving, let your requests be made known to God. And the peace of God, which surpasses all understanding, will guard your hearts and your thoughts in Christ Jesus.', 'Philippians 4:6–7 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 14),
  ('scripture-1-thessalonians-5-16-18', 'scripture', 'Pray without ceasing', 'Always rejoice. Pray without ceasing. In everything give thanks, for this is the will of God in Christ Jesus toward you.', '1 Thessalonians 5:16–18 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 15),
  ('scripture-james-5-16', 'scripture', 'Pray for one another', 'Confess your offenses to one another, and pray for one another, that you may be healed. The insistent prayer of a righteous person is powerfully effective.', 'James 5:16 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 16),
  ('scripture-galatians-6-2', 'scripture', 'Bear one another’s burdens', 'Bear one another’s burdens, and so fulfill the law of Christ.', 'Galatians 6:2 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 17),
  ('scripture-romans-8-26', 'scripture', 'When we don’t know what to pray', 'In the same way, the Spirit also helps our weaknesses, for we don’t know how to pray as we ought. But the Spirit himself makes intercession for us with groanings which can’t be uttered.', 'Romans 8:26 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 18),
  ('scripture-romans-12-12', 'scripture', 'Persistent in prayer', 'Rejoicing in hope; enduring in troubles; continuing steadfastly in prayer', 'Romans 12:12 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 19),
  ('scripture-hebrews-4-16', 'scripture', 'Come boldly', 'Let’s therefore draw near with boldness to the throne of grace, that we may receive mercy and may find grace for help in time of need.', 'Hebrews 4:16 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 20),
  ('scripture-1-john-5-14-15', 'scripture', 'Confidence in prayer', 'This is the boldness which we have toward him, that if we ask anything according to his will, he listens to us. And if we know that he listens to us, whatever we ask, we know that we have the petitions which we have asked of him.', '1 John 5:14–15 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 21),
  ('scripture-ephesians-6-18', 'scripture', 'Pray for all the saints', 'With all prayer and requests, praying at all times in the Spirit, and being watchful to this end in all perseverance and requests for all the saints', 'Ephesians 6:18 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 22),
  ('scripture-colossians-4-2', 'scripture', 'Watchful and thankful', 'Continue steadfastly in prayer, watching in it with thanksgiving', 'Colossians 4:2 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 23),
  ('scripture-psalm-145-18', 'scripture', 'The Lord is near', 'Yahweh is near to all those who call on him, to all who call on him in truth.', 'Psalm 145:18 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 24),
  ('scripture-psalm-46-10', 'scripture', 'Be still', '“Be still, and know that I am God. I will be exalted among the nations. I will be exalted in the earth.”', 'Psalm 46:10 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 25),
  ('scripture-jeremiah-33-3', 'scripture', 'Call to me', '‘Call to me, and I will answer you, and will show you great and difficult things, which you don’t know.’', 'Jeremiah 33:3 (WEB)', 'World English Bible (public domain)', 'https://ebible.org/web/', 26),
  ('practice-acts', 'practice', 'Pray with ACTS', 'Adoration: Begin by praising God for who he is. (“Our Father in heaven, may your name be kept holy.” Matthew 6:9)
